/// Scans the next symbol token, if any.
fn scan_symbol(&mut self) -> Option<Token> {
    let c = self.chars.peek()?;
    let token = match c {
        '.' => Token::Period,
        '=' => Token::Equal,
        '!' => {
            self.chars.next();
            if self.next_is('=') {
                Token::NotEqual
            } else {
                Token::Exclamation
            }
        }
        '>' => {
            self.chars.next();
            if self.next_is('=') {
                Token::GreaterThanOrEqual
            } else {
                Token::GreaterThan
            }
        }
        '<' => {
            self.chars.next();
            if self.next_is('=') {
                Token::LessThanOrEqual
            } else if self.next_is('>') {
                Token::LessOrGreaterThan
            } else {
                Token::LessThan
            }
        }
        '+' => Token::Plus,
        '-' => Token::Minus,
        '*' => Token::Asterisk,
        '/' => Token::Slash,
        '^' => Token::Caret,
        '%' => Token::Percent,
        '?' => Token::Question,
        ',' => Token::Comma,
        ';' => Token::Semicolon,
        '(' => Token::OpenParen,
        ')' => Token::CloseParen,
        _ => return None,
    };
    self.chars.next();
    Some(token)
}
